// The shape of docs.json, generated by docs/main.go in the falcon repository.

type DocExample = {
  name?: string // The suffix of ExampleFoo_suffix, if any
  code: string
  output?: string // What the example prints; go test checks it
};
type DocType = {
  name: string;
  doc: string;
  package?: string;
  methods?: DocType[];
  code?: string;
  examples?: DocExample[];
};
type DocFunction = {
  name: string;
  doc: string;
  package?: string;
  code?: string;
  examples?: DocExample[];
};
